const COMMAND_COMPONENT_SECTIONS=[
  {name:'Kitchen/Kitchenette',items:['Cabinets/Shelving','Carbon Monoxide Detectors','Ceiling','Chair(s)','Counter/Counter Tops','Door(s)','Electric Outlets/Switches','Floors/Carpets','Light Fixtures','Sink (including fixtures/plumbing)','Smoke Detectors','Sprinklers','Table','Trash and Recycling Receptacles','Wall(s)','Window Area/Glass (including screens)','Additional Items']},
  {name:'Appliances',items:['Dehumidifier','Dishwasher','Dryer','Freezer','Microwave','Range Vent/Hood/Exhaust Fan','Range/Cooktop/Stove','Refrigerator','Washer','Additional Items']},
  {name:'Bathroom',items:['Cabinets/Shelving','Carbon Monoxide Detectors','Ceiling','Counter/Counter Tops','Door(s)','Electric Outlets/Switches','Fan Vent/Ventilation/Exhaust Fans','Floors/Carpets','Light Fixtures','Mirrors','Radiator','Shower (including fixtures/joints)','Shower Curtain/Door/Rods','Sink (including fixtures/plumbing)','Smoke Detectors','Sprinklers','Toilet/Commode','Towel Rack','Tub (including fixtures)','Vanity','Wall(s)','Window Area/Glass (including screens)','Additional Items']},
  {name:'Bedroom',items:['Bedding/Linen','Built-In Furniture','Carbon Monoxide Detectors','Ceiling','Ceiling Fan','Closet Shelves','Curtain/Blinds','Door(s)','Electric Outlets/Switches','Floors/Carpets','Furniture','Gear Adrift (property not stored away)','Light Fixtures','Laundry','Locker/Closet','Smoke Detectors','Sprinklers','Trash','Wall(s)','Window Area/Glass (including screens)','Additional Items']},
  {name:'Living Area',items:['Built-In Furniture','Carbon Monoxide Detectors','Ceiling','Ceiling Fan','Closet Shelves','Curtain/Blinds','Door(s)','Electric Outlets/Switches','Floors/Carpets','Furniture','Gear Adrift (property not stored away)','Light Fixtures','Laundry','Locker/Closet','Smoke Detectors','Sprinklers','Trash','Wall(s)','Window Area/Glass (including screens)','Additional Items']}
];
const FURNITURE=[['Bed frame / single twin set','perMarine',1],['Twin mattress','perMarine',1],['Desk','perMarine',1],['Desk chair','perMarine',1],['Dresser','perMarine',1],['Wall locker / closet','perMarine',1],['Wall-unit secretary / additional desk unit','custom',0],['Framed mirror','perRoom',1],['Area rug','perRoom',1],['Floor lamp','perRoom',1],['Microwave','perRoom',1],['Small refrigerator','perRoom',1],['Window treatment / curtain','perRoom',1],['Dehumidifier','perRoom',1]].map(([item,mode,qty])=>({item,mode,qty}));
const RATINGS=[['','Select'],['G','G - Good'],['F','F - Fair'],['P','P - Poor'],['EHS','EHS'],['N/A','N/A']];
const CONDITION_CODES=[['','None'],['BR','BR - Broken (repair/replace)'],['BU','BU - Burned'],['C','C - Requires cleaning'],['CH','CH - Chipped'],['CL','CL - Clogged (total/partial)'],['CR','CR - Cracked'],['DA','DA - Damaged'],['FS','FS - Foul Smell'],['FWT','FWT - Fair Wear and Tear'],['MI','MI - Missing'],['MO','MO - Suspect Mold'],['ND','ND - Need Defrosting'],['NH','NH - Nail Hole'],['NP','NP - Needs Paint'],['NWT','NWT - Non-Fair Wear and Tear'],['R','R - Maintenance/repair required'],['S','S - Soiled'],['SC','SC - Scratch'],['SP','SP - Spot'],['ST','ST - Stained'],['TO','TO - Torn'],['WA','WA - Warped']];
const emptyState=()=>({version:APP_VERSION,settings:{installation:'MCAS Futenma',inspector:'',buildings:'',buildingManagers:'',acknowledged:false},records:[]});
let state=loadState(),draft=loadDraft(),route=draft?'inspection':'modules',pendingType='Check-In',deferredInstall=null;
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),dialogBody=document.querySelector('#dialogBody');

function loadState(){try{const saved=JSON.parse(localStorage.getItem(APP_KEY)),base=emptyState();if(!saved)return base;const settings={...base.settings,...(saved.settings||{})};if(!settings.buildings&&settings.buildingRoster)settings.buildings=String(settings.buildingRoster).split(/\r?\n/).map(x=>x.split('|')[0].trim()).filter(Boolean).join('\n');if(!settings.buildingManagers&&settings.buildingRoster)settings.buildingManagers=[...new Set(String(settings.buildingRoster).split(/\r?\n/).map(x=>x.split('|').slice(1).join('|').trim()).filter(Boolean))].join('\n');return{...base,...saved,settings}}catch{return emptyState()}}
function loadDraft(){try{return normalizeDraft(JSON.parse(localStorage.getItem(DRAFT_KEY)))}catch{return null}}
function normalizeDraft(d){if(!d)return null;d.ehsResponses=(d.ehsResponses||[]).map(r=>({...r,choices:r.choices||['Yes','No',...(r.allowNA?['N/A']:[])]}));d.sectionComments=d.sectionComments||{};d.componentSectionNA=d.componentSectionNA||{};d.followUp=d.followUp||[];d.signatures=d.signatures||{housingRep:'',resident:''};d.extraFields=d.extraFields||{fireAlarmInspectionDate:''};d.readings=d.readings||{temperature:{outdoor:'',unit:'',floor:'',bedroom:'',bathroom:'',comments:''},humidity:{outdoor:'',unit:'',floor:'',bedroom:'',bathroom:'',comments:''},dewPoint:{outdoor:'',unit:'',floor:'',bedroom:'',bathroom:'',comments:''}};return d}
function save(){state.version=APP_VERSION;localStorage.setItem(APP_KEY,JSON.stringify(state))}
function saveDraft(){draft?localStorage.setItem(DRAFT_KEY,JSON.stringify(draft)):localStorage.removeItem(DRAFT_KEY)}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function uid(){return crypto.randomUUID?crypto.randomUUID():'id-'+Date.now()+'-'+Math.random().toString(16).slice(2)}
function today(){return new Date().toISOString().slice(0,10)}
function fmtDate(v){if(!v)return'—';const[y,m,d]=String(v).slice(0,10).split('-');return`${d} ${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(m)-1]} ${y}`}
function val(id){return document.querySelector('#'+id)?.value.trim()||''}
function setRoute(next){route=next;render();window.scrollTo({top:0,behavior:'smooth'})}
function download(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function render(){document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route));app.innerHTML=route==='modules'?modulesView():route==='inspection'?inspectionView():route==='records'?recordsView():settingsView();bind()}
function settingsList(value){return[...new Set(String(value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean))]}
function buildingList(){return settingsList(state.settings.buildings)}
function managerList(){return settingsList(state.settings.buildingManagers)}
function ehsTemplate(type){return type==='Command-Directed'?COMMAND_EHS_SECTIONS:EHS_SECTIONS}
function componentTemplate(type){return type==='Command-Directed'?COMMAND_COMPONENT_SECTIONS:COMPONENT_SECTIONS}

function modulesView(){const pending=state.records.filter(r=>!r.emhUpdated).length;return`<div class="page-head"><div><h2>Field Modules</h2><p>Compact forms for field use and later eMH entry.</p></div></div>${!state.settings.acknowledged?`<div class="notice danger"><b>Draft supplement only.</b> Records and signatures remain in this browser until exported. <button class="button compact outline" data-action="acknowledge">Acknowledge</button></div><br>`:''}<div class="grid"><div class="card half module-card active-module"><div class="module-icon">⇥</div><div><h2>Check-In</h2><p class="muted">Pre-occupancy room-condition inspection before eMH check-in.</p></div><button class="button" data-action="start-type" data-id="Check-In">New Check-In</button></div><div class="card half module-card active-module"><div class="module-icon">⇤</div><div><h2>Check-Out</h2><p class="muted">Room-condition inspection for termination and turnover.</p></div><button class="button" data-action="start-type" data-id="Check-Out">New Check-Out</button></div><div class="card half module-card active-module"><div class="module-icon">▤</div><div><h2>Furniture Issued Items</h2><p class="muted">Quantity and condition verification for 1, 2, or 3 occupants.</p></div><button class="button" data-action="start-type" data-id="Furniture-Issued">New Furniture Record</button></div><div class="card half module-card active-module"><div class="module-icon">△</div><div><h2>Command-Directed</h2><p class="muted">Expanded checklist, environmental readings, building systems, and room components.</p></div><button class="button" data-action="start-type" data-id="Command-Directed">New Command Inspection</button></div><div class="card half module-card future-module"><div class="module-icon">◫</div><div><h2>Quarterly</h2><p class="muted">20% and 100% inspection program. Future module.</p></div><span class="badge">PLANNED</span></div><div class="card"><h3>Transfer Status</h3><div class="record"><span>Completed records</span><b>${state.records.length}</b></div><div class="record"><span>Awaiting eMH update</span><b>${pending}</b></div></div></div>`}
function inspectionView(){if(draft)return editorView();return`<div class="page-head"><div><h2>Inspection Forms</h2><p>Select the form to begin.</p></div></div><div class="grid"><button class="card choice-card" data-action="start-type" data-id="Check-In"><b>Check-In</b><span>Pre-occupancy readiness</span></button><button class="card choice-card" data-action="start-type" data-id="Check-Out"><b>Check-Out</b><span>Termination and turnover</span></button><button class="card choice-card" data-action="start-type" data-id="Furniture-Issued"><b>Furniture Issued Items</b><span>Separate inventory verification</span></button><button class="card choice-card" data-action="start-type" data-id="Command-Directed"><b>Command-Directed</b><span>Expanded eMH inspection</span></button></div>`}
function startView(type){const buildings=buildingList(),managers=managerList(),isFurniture=type==='Furniture-Issued';return`<div class="page-head"><div><h2>${type==='Furniture-Issued'?'Furniture Issued Items':type+' Inspection'}</h2><p>Enter the room information, then begin the form.</p></div><button class="button compact outline" data-action="close-start">Cancel</button></div><form id="startForm" class="card form-grid"><input id="inspectionType" type="hidden" value="${type}"><div class="field"><label>Date *</label><input id="startDate" type="date" value="${today()}" required></div><div class="field"><label>Building Manager / Housing Rep *</label><input id="startInspector" list="managerList" value="${esc(state.settings.inspector)}" required><datalist id="managerList">${managers.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></div><div class="field"><label>Building number *</label><input id="startBuilding" list="buildingList" required><datalist id="buildingList">${buildings.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></div><div class="field"><label>Room number *</label><input id="startRoom" required></div>${isFurniture?`<div class="field"><label>Furniture sets / occupants *</label><select id="startOccupants" required><option value="1">1</option><option value="2" selected>2</option><option value="3">3</option></select></div>`:'<input id="startOccupants" type="hidden" value="1">'}<div class="field"><label>Inspection basis</label><select id="startBasis"><option>Physical room inspection</option><option>Previous inspection plus verification walk</option></select></div>${type==='Command-Directed'?`<div class="field"><label>Inspection number</label><input id="startInspectionNumber" placeholder="Optional"></div><div class="field"><label>Re-inspection</label><select id="startReinspection"><option value="No">No</option><option value="Yes">Yes</option></select></div>`:''}<div class="field full"><button class="button full" type="submit">Begin ${type==='Furniture-Issued'?'Furniture Record':type}</button></div></form>`}
function inspectionLabel(type){return type==='Check-Out'?'CHECK-OUT/TERMINATION':type==='Command-Directed'?'COMMAND DIRECTED':type==='Furniture-Issued'?'FURNITURE ISSUED ITEMS':'CHECK-IN'}
function editorView(){const isFurniture=draft.type==='Furniture-Issued',answered=draft.ehsResponses.filter(r=>r.answer).length,componentsDone=draft.componentResponses.filter(r=>r.rating).length,reviewed=draft.furniture.filter(f=>f.rating&&f.present!=='').length,total=isFurniture?draft.furniture.length:draft.ehsResponses.length+draft.componentResponses.length,pct=total?Math.round((isFurniture?reviewed:answered+componentsDone)/total*100):0;return`<div class="page-head compact-head"><div><span class="badge">${esc(draft.type.toUpperCase())}</span><h2>Building ${esc(draft.building)} · Room ${esc(draft.room)}</h2><p>${fmtDate(draft.date)}${isFurniture?` · ${draft.occupants} furniture set${draft.occupants===1?'':'s'}`:''}</p></div><button class="button compact outline" data-action="cancel-draft">Cancel</button></div><div class="inspection-toolbar"><div class="card compact-toolbar"><span class="badge">${pct}% REVIEWED</span><div class="actions">${isFurniture?'':`<button class="button compact secondary" data-action="all-yes">All Blank Yes</button><button class="button compact secondary" data-action="components-good">Components Good</button>`}${isFurniture?`<button class="button compact secondary" data-action="inventory-good">Furniture Good</button>`:''}<button class="button compact success" data-action="complete">Complete</button></div><div class="progress"><i style="width:${pct}%"></i></div></div></div><div class="paper-form"><div class="paper-title"><b>${isFurniture?'Furniture Issued Items':'Unaccompanied Housing Inspection Checklist'}</b><span>${inspectionLabel(draft.type)} · MCB Camp S. D. Butler · MCAS Futenma</span></div><div class="paper-meta"><span><b>Date</b>${fmtDate(draft.date)}</span><span><b>Building</b>${esc(draft.building)}</span><span><b>Room</b>${esc(draft.room)}</span><span><b>Building Manager / Housing Rep</b>${esc(draft.inspector)}</span>${draft.inspectionNumber?`<span><b>Inspection Number</b>${esc(draft.inspectionNumber)}</span>`:''}${draft.type==='Command-Directed'?`<span><b>Re-inspection</b>${esc(draft.reinspection||'No')}</span>`:''}</div>${signaturePadsView()}${isFurniture?`${ratingLegend()}${furnitureTable()}`:`${ehsChecklist()}${ratingLegend()}${componentChecklist()}${followUpView()}`}<div class="overall-box"><label>${isFurniture?'Furniture Comments':'Inspection Comments'}</label><textarea id="overallNotes">${esc(draft.overallNotes||'')}</textarea></div><div class="paper-actions"><button class="button success" data-action="complete">Complete ${esc(isFurniture?'Furniture Record':draft.type+' Inspection')}</button></div></div>`}
function signaturePadsView(){return`<section class="signature-section"><div class="signature-box"><div class="signature-label"><b>Building Manager / Housing Rep Signature</b><button class="signature-clear" data-clear-signature="housingRep" type="button">Clear</button></div><canvas data-signature="housingRep" width="600" height="120" aria-label="Building Manager signature pad"></canvas></div><div class="signature-box"><div class="signature-label"><b>Resident Signature (if applicable)</b><button class="signature-clear" data-clear-signature="resident" type="button">Clear</button></div><canvas data-signature="resident" width="600" height="120" aria-label="Resident signature pad"></canvas></div></section>`}
function commandReadingsView(){const labels=[['temperature','Temperature (T) 68-80°F'],['humidity','Relative Humidity (RH) 30-50%'],['dewPoint','Dew Point']],locations=[['outdoor','Outdoor'],['unit','Unit'],['floor','Floor Outside Unit'],['bedroom','Bedroom'],['bathroom','Bathroom']];return`<div class="readings-block"><div class="readings-subtitle">Measurements and Readings</div><div class="compact-table-wrap"><table class="paper-table readings-table"><thead><tr><th>Reading</th>${locations.map(x=>`<th>${x[1]}</th>`).join('')}<th>Comments</th></tr></thead><tbody>${labels.map(([key,label])=>`<tr><td>${label}</td>${locations.map(([loc])=>`<td><input data-reading="${key}" data-reading-location="${loc}" type="number" step="0.1" value="${esc(draft.readings?.[key]?.[loc]||'')}" ${key==='dewPoint'?'readonly':''}></td>`).join('')}<td><input data-reading="${key}" data-reading-location="comments" value="${esc(draft.readings?.[key]?.comments||'')}"></td></tr>`).join('')}</tbody></table></div></div>`}
function ehsChecklist(){return ehsTemplate(draft.type).map(s=>{const rows=draft.ehsResponses.filter(r=>r.section===s.name),columns=['Yes','No',...(['Unknown','N/A'].filter(v=>rows.some(r=>r.choices.includes(v))))];return`<section class="form-section"><div class="form-section-title">${esc(s.name)}</div>${draft.type==='Command-Directed'&&s.name==='Mold/Moisture Control'?commandReadingsView():''}<table class="paper-table ehs-table"><colgroup>${columns.map(()=>'<col class="mark-col">').join('')}<col></colgroup><thead><tr>${columns.map(v=>`<th>${v==='Unknown'?'UNK':v}</th>`).join('')}<th>Question</th></tr></thead><tbody>${rows.map(r=>ehsRow(r,columns)).join('')}</tbody></table>${draft.type==='Command-Directed'&&s.name.startsWith('Smoke and Carbon')?`<label class="inline-extra">Date of latest Fire Alarm Control System Inspection:<input data-extra-field="fireAlarmInspectionDate" type="date" value="${esc(draft.extraFields?.fireAlarmInspectionDate||'')}"></label>`:''}<label class="section-comments">If you answered “No” to any question above, provide details:<textarea data-section-comment="${esc(s.name)}">${esc(draft.sectionComments[s.name]||'')}</textarea></label></section>`}).join('')}
function ehsRow(r,columns){return`<tr data-ehs-id="${r.id}" class="${r.answer==='No'?'deficient-row':''}">${columns.map(v=>`<td class="mark-cell">${r.choices.includes(v)?`<label class="square-choice"><input type="radio" name="e-${r.id}" value="${v}" ${r.answer===v?'checked':''}><span>${v==='Yes'?'Y':v==='No'?'N':v==='Unknown'?'?':'—'}</span></label>`:'<span class="not-rated">—</span>'}</td>`).join('')}<td>${esc(r.item)}</td></tr>`}
function ratingOptions(value){return RATINGS.map(([v,label])=>`<option value="${v}" ${value===v?'selected':''}>${label}</option>`).join('')}
function conditionOptions(value){return CONDITION_CODES.map(([v,label])=>`<option value="${v}" ${value===v?'selected':''}>${label}</option>`).join('')}
function ratingLegend(){return`<div class="rating-legend"><b>Component Rating</b><span><strong>G</strong> Good</span><span><strong>F</strong> Fair</span><span><strong>P</strong> Poor</span><span><strong>EHS</strong> Environmental, Health, Safety</span><span><strong>N/A</strong> Not Applicable</span></div>`}
function componentChecklist(){return componentTemplate(draft.type).map(s=>{const rows=draft.componentResponses.filter(r=>r.section===s.name),na=draft.componentSectionNA[s.name];return`<section class="form-section"><div class="form-section-title">${esc(s.name)}</div><label class="section-na"><input type="checkbox" data-component-na="${esc(s.name)}" ${na?'checked':''}> Mark section as N/A</label><div class="compact-table-wrap"><table class="paper-table component-table"><colgroup><col class="component-col"><col class="rating-col"><col class="code-col"><col></colgroup><thead><tr><th>Component</th><th>Rating</th><th>Condition</th><th>Comments</th></tr></thead><tbody>${rows.map(componentRow).join('')}</tbody></table></div></section>`}).join('')}
function componentRow(r){return`<tr data-component-id="${r.id}" class="${['P','EHS'].includes(r.rating)?'deficient-row':''}"><td>${esc(r.item)}</td><td><select data-component-field="rating" ${draft.componentSectionNA[r.section]?'disabled':''}>${ratingOptions(r.rating)}</select></td><td><select data-component-field="condition" ${draft.componentSectionNA[r.section]?'disabled':''}>${conditionOptions(r.condition)}</select></td><td><input data-component-field="comments" value="${esc(r.comments||'')}" placeholder="Comments" ${draft.componentSectionNA[r.section]?'disabled':''}></td></tr>`}
function furnitureDeficient(f){return(f.present!==''&&f.present<f.expected)||['P','EHS'].includes(f.rating)||['BR','MI','R'].includes(f.condition)}
function furnitureTable(){return`<section class="form-section"><div class="form-section-title">Furniture / Issued Items</div><div class="compact-table-wrap"><table class="paper-table furniture-table"><colgroup><col class="f-item"><col class="f-qty"><col class="f-qty"><col class="rating-col"><col class="code-col"><col></colgroup><thead><tr><th>Item</th><th>Expected</th><th>Present</th><th>Rating</th><th>Condition</th><th>Comments</th></tr></thead><tbody>${draft.furniture.map(f=>`<tr data-furniture-id="${f.id}" class="${furnitureDeficient(f)?'deficient-row':''}"><td>${esc(f.item)}<small>${f.mode==='perMarine'?'per Marine':f.mode==='perRoom'?'per room':'adjustable'}</small></td><td><input data-furniture-field="expected" type="number" min="0" value="${f.expected}"></td><td><input data-furniture-field="present" type="number" min="0" value="${f.present}"></td><td><select data-furniture-field="rating">${ratingOptions(f.rating)}</select></td><td><select data-furniture-field="condition">${conditionOptions(f.condition)}</select></td><td><input data-furniture-field="comments" value="${esc(f.comments||'')}" placeholder="Comments"></td></tr>`).join('')}</tbody></table></div></section>`}
function followUpView(){const options=['None','Re-Inspection Required','Work Request Required','In-House Maintenance','EHS - General Safety',...(draft.type==='Command-Directed'?['EHS - Asbestos','EHS - Radon']:[]),'EHS - Water','EHS - Mold/Moisture Control','EHS - HVAC','EHS - Pest Management','EHS - Smoke and Carbon Monoxide Detectors and Fire Sprinklers'];return`<section class="form-section"><div class="form-section-title">Follow-up Actions</div><div class="follow-grid">${options.map(x=>`<label><input type="checkbox" data-follow-up="${esc(x)}" ${draft.followUp.includes(x)?'checked':''}> ${esc(x)}</label>`).join('')}</div><div class="calculated-result"><b>Calculated inspection result</b><span>${esc(outcomeFor(draft))}</span></div></section>`}
function recordsView(){const records=state.records.slice().sort((a,b)=>String(b.completedAt).localeCompare(String(a.completedAt)));return`<div class="page-head"><div><h2>Inspection Records</h2><p>${records.length} completed</p></div><div class="actions"><button class="button compact" data-action="export-all">Export Excel</button><button class="button compact secondary" data-action="backup">Backup</button></div></div><div class="card">${records.length?records.map(recordRow).join(''):'<div class="empty">No completed inspections.</div>'}</div>`}
function recordRow(r){const fail=r.outcome==='Fail'||/Hold|Not Ready|Not Clear/.test(r.outcome),condition=/Condition|Discrepancies/.test(r.outcome);return`<div class="record"><div><div class="record-title">${esc(r.type)} · Building ${esc(r.building)} · Room ${esc(r.room)}</div><div class="record-meta">${fmtDate(r.date)} · ${esc(r.inspector)}</div><div class="actions"><span class="badge ${fail?'fail':condition?'pending':'pass'}">${esc(r.outcome)}</span><span class="badge ${r.emhUpdated?'pass':'pending'}">eMH ${r.emhUpdated?'UPDATED':'PENDING'}</span></div></div><button class="button compact outline" data-action="open-record" data-id="${r.id}">Open</button></div>`}
function settingsView(){return`<div class="page-head"><div><h2>Settings</h2><p>Defaults, buildings, Building Managers, and local data.</p></div></div><div class="stack"><form id="settingsForm" class="card form-grid"><div class="field"><label>Installation</label><input id="setInstallation" value="${esc(state.settings.installation)}"></div><div class="field"><label>Default Building Manager / Housing Rep</label><input id="setInspector" value="${esc(state.settings.inspector)}"></div><div class="field"><label>Building numbers</label><textarea id="setBuildings" class="roster-input" placeholder="400&#10;401&#10;402">${esc(state.settings.buildings||'')}</textarea><p class="small muted">Enter one building number per line.</p></div><div class="field"><label>Building Managers</label><textarea id="setBuildingManagers" class="roster-input" placeholder="Emanuel Larkin&#10;Building Manager Name">${esc(state.settings.buildingManagers||'')}</textarea><p class="small muted">Enter one Building Manager per line.</p></div><div class="field full"><button class="button" type="submit">Save Settings</button></div></form><div class="card"><h3>Local Data</h3><p class="small muted">Drafts, completed records, and signatures stay in this browser. Export before clearing browser data or changing devices.</p><div class="actions"><button class="button" data-action="export-all">Export Excel</button><button class="button secondary" data-action="backup">Export JSON Backup</button><button class="button danger" data-action="clear-data">Erase All Data</button></div></div></div>`}

function bind(){document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>setRoute(b.dataset.route));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>{e.preventDefault();action(b.dataset.action,b.dataset.id)});const start=document.querySelector('#startForm');if(start)start.onsubmit=e=>{e.preventDefault();beginInspection()};const settings=document.querySelector('#settingsForm');if(settings)settings.onsubmit=e=>{e.preventDefault();state.settings.installation=val('setInstallation');state.settings.inspector=val('setInspector');state.settings.buildings=document.querySelector('#setBuildings')?.value.trim()||'';state.settings.buildingManagers=document.querySelector('#setBuildingManagers')?.value.trim()||'';save();showDialog('Settings saved','Building and Building Manager lists updated separately.');render()};if(!draft)return;document.querySelectorAll('[data-ehs-id]').forEach(row=>row.querySelectorAll('input[type="radio"]').forEach(i=>i.onchange=()=>{draft.ehsResponses.find(x=>x.id===row.dataset.ehsId).answer=i.value;saveDraft();render()}));document.querySelectorAll('[data-section-comment]').forEach(f=>f.oninput=()=>{draft.sectionComments[f.dataset.sectionComment]=f.value;saveDraft()});document.querySelectorAll('[data-component-id]').forEach(row=>row.querySelectorAll('[data-component-field]').forEach(f=>f.onchange=()=>{draft.componentResponses.find(x=>x.id===row.dataset.componentId)[f.dataset.componentField]=f.value;saveDraft();render()}));document.querySelectorAll('[data-component-na]').forEach(f=>f.onchange=()=>{draft.componentSectionNA[f.dataset.componentNa]=f.checked;draft.componentResponses.filter(x=>x.section===f.dataset.componentNa).forEach(x=>{if(f.checked){x.rating='N/A';x.condition='';x.comments=''}});saveDraft();render()});document.querySelectorAll('[data-furniture-id]').forEach(row=>row.querySelectorAll('[data-furniture-field]').forEach(f=>f.onchange=()=>{const item=draft.furniture.find(x=>x.id===row.dataset.furnitureId);item[f.dataset.furnitureField]=f.type==='number'?(f.value===''?'':Math.max(0,Number(f.value)||0)):f.value;saveDraft();render()}));document.querySelectorAll('[data-reading]').forEach(f=>f.onchange=()=>{draft.readings[f.dataset.reading][f.dataset.readingLocation]=f.value;if(['temperature','humidity'].includes(f.dataset.reading))calcReadings();saveDraft();render()});document.querySelectorAll('[data-extra-field]').forEach(f=>f.onchange=()=>{draft.extraFields[f.dataset.extraField]=f.value;saveDraft()});document.querySelectorAll('[data-follow-up]').forEach(f=>f.onchange=()=>{draft.followUp=f.checked?[...new Set([...draft.followUp,f.dataset.followUp])]:draft.followUp.filter(x=>x!==f.dataset.followUp);saveDraft()});bindSignaturePads();const overall=document.querySelector('#overallNotes');if(overall)overall.oninput=()=>{draft.overallNotes=overall.value;saveDraft()}}
function bindSignaturePads(){document.querySelectorAll('[data-signature]').forEach(canvas=>{const key=canvas.dataset.signature,ctx=canvas.getContext('2d');ctx.lineWidth=2.2;ctx.lineCap='round';ctx.strokeStyle='#17202a';if(draft.signatures[key]){const img=new Image();img.onload=()=>ctx.drawImage(img,0,0,canvas.width,canvas.height);img.src=draft.signatures[key]}let drawing=false;const point=e=>{const r=canvas.getBoundingClientRect(),p=e.touches?.[0]||e;return{x:(p.clientX-r.left)*(canvas.width/r.width),y:(p.clientY-r.top)*(canvas.height/r.height)}};const start=e=>{e.preventDefault();drawing=true;const p=point(e);ctx.beginPath();ctx.moveTo(p.x,p.y)};const move=e=>{if(!drawing)return;e.preventDefault();const p=point(e);ctx.lineTo(p.x,p.y);ctx.stroke()};const end=e=>{if(!drawing)return;e.preventDefault();drawing=false;draft.signatures[key]=canvas.toDataURL('image/png');saveDraft()};canvas.addEventListener('pointerdown',start);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',end);canvas.addEventListener('pointerleave',end)});document.querySelectorAll('[data-clear-signature]').forEach(b=>b.onclick=()=>{draft.signatures[b.dataset.clearSignature]='';saveDraft();render()})}
function action(name,id){if(name==='acknowledge'){state.settings.acknowledged=true;save();render()}if(name==='start-type'){pendingType=id;app.innerHTML=startView(id);bind()}if(name==='close-start'){route='inspection';render()}if(name==='cancel-draft'&&confirm('Discard this unfinished inspection?')){draft=null;saveDraft();render()}if(name==='all-yes'){draft.ehsResponses.forEach(r=>{if(!r.answer)r.answer='Yes'});saveDraft();render()}if(name==='components-good'){draft.componentResponses.forEach(r=>{if(!r.rating)r.rating='G'});saveDraft();render()}if(name==='inventory-good'){draft.furniture.forEach(f=>{f.present=f.expected;f.rating='G'});saveDraft();render()}if(name==='complete')completeInspection();if(name==='open-record')openRecord(id);if(name==='export-all')exportExcel(state.records);if(name==='backup')download(`UH-field-app-backup-${today()}.json`,new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));if(name==='clear-data')clearData()}
function beginInspection(){const type=val('inspectionType')||pendingType,building=val('startBuilding'),room=val('startRoom'),occupants=Math.max(1,Math.min(3,Number(val('startOccupants'))||1)),prefix=type==='Check-In'?'CI':type==='Check-Out'?'CO':type==='Furniture-Issued'?'FI':'CD';if(!building||!room||!val('startInspector'))return;draft={id:uid(),recordNumber:`${prefix}-${building.replace(/\W/g,'')}-${room.replace(/\W/g,'')}-${today().replaceAll('-','')}-${String(Date.now()).slice(-4)}`,type,date:val('startDate'),building,room,occupants,inspector:val('startInspector'),basis:val('startBasis'),inspectionNumber:val('startInspectionNumber'),reinspection:val('startReinspection')||'No',createdAt:new Date().toISOString(),completedAt:'',emhUpdated:false,overallNotes:'',sectionComments:{},componentSectionNA:{},followUp:[],signatures:{housingRep:'',resident:''},extraFields:{fireAlarmInspectionDate:''},readings:{temperature:{outdoor:'',unit:'',floor:'',bedroom:'',bathroom:'',comments:''},humidity:{outdoor:'',unit:'',floor:'',bedroom:'',bathroom:'',comments:''},dewPoint:{outdoor:'',unit:'',floor:'',bedroom:'',bathroom:'',comments:''}},ehsResponses:[],componentResponses:[],furniture:[]};if(type==='Furniture-Issued'){draft.furniture=FURNITURE.map(f=>({id:uid(),item:f.item,mode:f.mode,expected:f.mode==='perMarine'?f.qty*occupants:f.qty,present:'',rating:'',condition:'',comments:''}))}else{ehsTemplate(type).forEach(s=>{draft.sectionComments[s.name]='';s.items.forEach(([item,extras])=>{const choices=['Yes','No',...(Array.isArray(extras)?extras:(extras?['N/A']:[]))];draft.ehsResponses.push({id:uid(),section:s.name,item,choices:[...new Set(choices)],answer:''})})});componentTemplate(type).forEach(s=>{draft.componentSectionNA[s.name]=false;s.items.forEach(item=>draft.componentResponses.push({id:uid(),section:s.name,item,rating:'',condition:'',comments:''}))})}saveDraft();route='inspection';render()}
function calcReadings(){for(const loc of ['outdoor','unit','floor','bedroom','bathroom']){const t=Number(draft.readings.temperature[loc]),rh=Number(draft.readings.humidity[loc]);draft.readings.dewPoint[loc]=draft.readings.temperature[loc]!==''&&draft.readings.humidity[loc]!==''&&Number.isFinite(t)&&Number.isFinite(rh)?(t-(9/25)*(100-rh)).toFixed(1):''}}
function outcomeFor(r){if(r.type==='Furniture-Issued')return r.furniture.some(f=>furnitureDeficient(f))?'Complete with Discrepancies':'Complete';const ehsFail=r.ehsResponses.some(x=>x.answer==='No')||r.componentResponses.some(x=>x.rating==='EHS');if(ehsFail)return'Fail';const componentIssue=r.componentResponses.some(x=>['F','P'].includes(x.rating)||x.condition);if(componentIssue)return'Pass with Condition';return'Pass'}
function completeInspection(){const isFurniture=draft.type==='Furniture-Issued',unanswered=draft.ehsResponses.filter(r=>!r.answer);if(unanswered.length)return showDialog('Checklist incomplete',`${unanswered.length} checklist item${unanswered.length===1?' is':'s are'} unanswered.`);const unrated=draft.componentResponses.filter(r=>!draft.componentSectionNA[r.section]&&!r.rating);if(unrated.length)return showDialog('Component ratings incomplete',`${unrated.length} component${unrated.length===1?' needs':'s need'} a rating.`);const unreviewed=isFurniture?draft.furniture.filter(f=>f.present===''||!f.rating):[];if(unreviewed.length)return showDialog('Furniture incomplete',`${unreviewed.length} furniture item${unreviewed.length===1?' needs':'s need'} a present quantity and rating.`);const missingSectionNotes=ehsTemplate(draft.type).filter(s=>draft.ehsResponses.some(r=>r.section===s.name&&r.answer==='No')&&!String(draft.sectionComments[s.name]||'').trim());if(missingSectionNotes.length)return showDialog('Section details required',`Add details for: ${missingSectionNotes.map(s=>s.name).join(', ')}.`);const missingComments=[...draft.componentResponses.filter(r=>(['P','EHS'].includes(r.rating)||r.condition)&&!r.comments.trim()),...(isFurniture?draft.furniture.filter(f=>furnitureDeficient(f)&&!f.comments.trim()):[])];if(missingComments.length)return showDialog('Comments required',`${missingComments.length} deficient item${missingComments.length===1?' needs':'s need'} a comment.`);draft.completedAt=new Date().toISOString();draft.outcome=outcomeFor(draft);state.records.unshift(structuredClone(draft));save();const id=draft.id;draft=null;saveDraft();route='records';render();openRecord(id)}
function openRecord(id){const r=state.records.find(x=>x.id===id);if(!r)return;const deficiencies=[...(r.ehsResponses||[]).filter(x=>x.answer==='No').map(x=>`${x.section}: ${x.item} - ${r.sectionComments?.[x.section]||''}`),...(r.componentResponses||[]).filter(x=>['P','EHS'].includes(x.rating)||x.condition).map(x=>`${x.section}: ${x.item} - ${x.rating}${x.condition?' / '+x.condition:''} - ${x.comments}`),...(r.furniture||[]).filter(f=>furnitureDeficient(f)).map(f=>`${f.item}: expected ${f.expected}, present ${f.present}, ${f.rating}${f.condition?' / '+f.condition:''} - ${f.comments}`)];showDialog(`${esc(r.type)} · Bldg ${esc(r.building)} · Room ${esc(r.room)}`,`<div class="stack"><div class="notice"><b>${esc(r.outcome)}</b><div class="small">${esc(r.recordNumber)}</div></div><div class="small"><b>Date:</b> ${fmtDate(r.date)}<br><b>Building Manager:</b> ${esc(r.inspector)}<br><b>BM signature:</b> ${r.signatures?.housingRep?'Captured':'Not captured'}<br><b>Resident signature:</b> ${r.signatures?.resident?'Captured':'Not captured'}<br><b>eMH:</b> ${r.emhUpdated?'Updated':'Pending manual entry'}</div>${deficiencies.length?`<div><h3>Deficiencies</h3>${deficiencies.map(x=>`<div class="notice warn record-note">${esc(x)}</div>`).join('')}</div>`:'<div class="notice">No deficiencies recorded.</div>'}${r.type==='Check-In'?'<div class="notice"><b>15-Day QSRMax Notice</b><div class="small">The Marine should report pre-existing discrepancies or repairs through QSRMax within 15 days of occupancy.</div></div>':''}<div class="actions"><button class="button" id="toggleEmh">${r.emhUpdated?'Mark eMH Pending':'Mark eMH Updated'}</button><button class="button secondary" id="exportOne">Export Record</button><button class="button outline" id="closeRecord">Close</button><button class="button danger" id="deleteRecord">Delete</button></div></div>`);document.querySelector('#toggleEmh').onclick=()=>{r.emhUpdated=!r.emhUpdated;save();closeDialog();render()};document.querySelector('#exportOne').onclick=()=>exportExcel([r]);document.querySelector('#closeRecord').onclick=closeDialog;document.querySelector('#deleteRecord').onclick=()=>{if(confirm('Delete this inspection record?')){state.records=state.records.filter(x=>x.id!==id);save();closeDialog();render()}}}
function clearData(){if(!confirm('Erase all local inspection records? Export first.'))return;if(!confirm('Final confirmation: erase all records and drafts?'))return;localStorage.removeItem(APP_KEY);localStorage.removeItem(DRAFT_KEY);state=emptyState();draft=null;render()}
function showDialog(title,content){dialogBody.innerHTML=`<h2>${title}</h2>${content.trim().startsWith('<')?content:`<p>${content}</p><div class="actions"><button class="button secondary" id="closeDialog">Close</button></div>`}`;dialog.showModal();const close=document.querySelector('#closeDialog');if(close)close.onclick=closeDialog}
function closeDialog(){dialog.close()}dialog.addEventListener('click',e=>{if(e.target===dialog)closeDialog()});

function exportExcel(records){const list=records||state.records,sheets=[{name:'Inspection Summary',rows:[['Record Number','eMH Inspection Number','Type','Date','Installation','Building','Room','Furniture Sets','Building Manager / Housing Rep','Basis','Re-inspection','Fire Alarm Inspection Date','Outcome','Follow-up Actions','BM Signature Captured','Resident Signature Captured','eMH Updated','Overall Comments'],...list.map(r=>[r.recordNumber,r.inspectionNumber||'',r.type,r.date,state.settings.installation,r.building,r.room,r.occupants,r.inspector,r.basis,r.reinspection||'',r.extraFields?.fireAlarmInspectionDate||'',r.outcome,(r.followUp||[]).join('; '),r.signatures?.housingRep?'Yes':'No',r.signatures?.resident?'Yes':'No',r.emhUpdated?'Yes':'No',r.overallNotes])]},{name:'EHS Checklist',rows:[['Record Number','Type','Date','Building','Room','Section','Question','Answer','Section Details'],...list.flatMap(r=>(r.ehsResponses||[]).map(x=>[r.recordNumber,r.type,r.date,r.building,r.room,x.section,x.item,x.answer,r.sectionComments?.[x.section]||'']))]},{name:'Components',rows:[['Record Number','Type','Date','Building','Room','Section','Component','Rating','Condition Code','Comments'],...list.flatMap(r=>(r.componentResponses||[]).map(x=>[r.recordNumber,r.type,r.date,r.building,r.room,x.section,x.item,x.rating,x.condition,x.comments]))]},{name:'Furniture',rows:[['Record Number','Type','Date','Building','Room','Furniture Sets','Item','Quantity Rule','Expected','Present','Missing','Rating','Condition Code','Comments'],...list.flatMap(r=>(r.furniture||[]).map(f=>[r.recordNumber,r.type,r.date,r.building,r.room,r.occupants,f.item,f.mode,f.expected,f.present,f.present===''?'':Math.max(0,f.expected-f.present),f.rating,f.condition,f.comments]))]},{name:'Environmental Readings',rows:[['Record Number','Type','Date','Building','Room','Reading','Outdoor','Unit','Floor Outside Unit','Bedroom','Bathroom','Comments'],...list.flatMap(r=>r.readings?['temperature','humidity','dewPoint'].map(key=>[r.recordNumber,r.type,r.date,r.building,r.room,key,r.readings[key].outdoor,r.readings[key].unit,r.readings[key].floor,r.readings[key].bedroom,r.readings[key].bathroom,r.readings[key].comments]):[])]},{name:'Deficiencies',rows:[['Record Number','Type','Date','Building','Room','Category','Item','Rating or Answer','Condition','Comments'],...list.flatMap(r=>[...(r.ehsResponses||[]).filter(x=>x.answer==='No').map(x=>[r.recordNumber,r.type,r.date,r.building,r.room,x.section,x.item,x.answer,'',r.sectionComments?.[x.section]||'']),...(r.componentResponses||[]).filter(x=>['P','EHS'].includes(x.rating)||x.condition).map(x=>[r.recordNumber,r.type,r.date,r.building,r.room,x.section,x.item,x.rating,x.condition,x.comments]),...(r.furniture||[]).filter(f=>furnitureDeficient(f)).map(f=>[r.recordNumber,r.type,r.date,r.building,r.room,'Furniture',f.item,f.rating,f.condition,`Expected ${f.expected}; present ${f.present}. ${f.comments||''}`])])]}];download(`UH-inspections-${today()}.xlsx`,buildXlsx(sheets))}

function buildXlsx(sheets){const now=new Date().toISOString(),files={'[Content_Types].xml':`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>${sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`,'_rels/.rels':`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/></Relationships>`,'docProps/core.xml':`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>UH Field Inspections</dc:title><dc:creator>UH Field App</dc:creator><dcterms:created xsi:type="dcterms:W3CDTF">${now}</dcterms:created></cp:coreProperties>`,'xl/workbook.xml':`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.map((s,i)=>`<sheet name="${xml(s.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`,'xl/_rels/workbook.xml.rels':`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="rId${sheets.length+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`,'xl/styles.xml':`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF0B1F33"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles><dxfs count="0"/><tableStyles count="0"/></styleSheet>`};sheets.forEach((s,i)=>files[`xl/worksheets/sheet${i+1}.xml`]=sheetXml(s));return zipStore(files,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')}
function sheetXml(sheet){const rows=sheet.rows.map((row,ri)=>`<row r="${ri+1}">${row.map((v,ci)=>cellXml(v,ri,ci)).join('')}</row>`).join(''),max=Math.max(1,...sheet.rows.map(r=>r.length));return`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>${Array.from({length:max},(_,i)=>`<col min="${i+1}" max="${i+1}" width="${i<6?18:28}" customWidth="1"/>`).join('')}</cols><sheetData>${rows}</sheetData><autoFilter ref="A1:${colName(max-1)}${Math.max(1,sheet.rows.length)}"/></worksheet>`}
function cellXml(v,ri,ci){const ref=colName(ci)+(ri+1);if(typeof v==='number')return`<c r="${ref}"><v>${v}</v></c>`;return`<c r="${ref}" t="inlineStr"${ri===0?' s="1"':''}><is><t xml:space="preserve">${xml(v??'')}</t></is></c>`}
function colName(n){let s='';do{s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26)-1}while(n>=0);return s}
function xml(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c])).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'')}
function zipStore(fileMap,mime){const enc=new TextEncoder(),parts=[],central=[];let offset=0;Object.entries(fileMap).forEach(([name,text])=>{const n=enc.encode(name),data=enc.encode(text),crc=crc32(data),time=dosTime(new Date()),local=new Uint8Array(30+n.length),d=new DataView(local.buffer);d.setUint32(0,0x04034b50,true);d.setUint16(4,20,true);d.setUint16(8,0,true);d.setUint16(10,time.time,true);d.setUint16(12,time.date,true);d.setUint32(14,crc,true);d.setUint32(18,data.length,true);d.setUint32(22,data.length,true);d.setUint16(26,n.length,true);local.set(n,30);parts.push(local,data);const c=new Uint8Array(46+n.length),cd=new DataView(c.buffer);cd.setUint32(0,0x02014b50,true);cd.setUint16(4,20,true);cd.setUint16(6,20,true);cd.setUint16(12,time.time,true);cd.setUint16(14,time.date,true);cd.setUint32(16,crc,true);cd.setUint32(20,data.length,true);cd.setUint32(24,data.length,true);cd.setUint16(28,n.length,true);cd.setUint32(42,offset,true);c.set(n,46);central.push(c);offset+=local.length+data.length});const size=central.reduce((n,p)=>n+p.length,0),end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,central.length,true);e.setUint16(10,central.length,true);e.setUint32(12,size,true);e.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:mime})}
function dosTime(date){return{time:(date.getHours()<<11)|(date.getMinutes()<<5)|(date.getSeconds()>>1),date:((date.getFullYear()-1980)<<9)|((date.getMonth()+1)<<5)|date.getDate()}}
const CRC_TABLE=(()=>{const t=new Uint32Array(256);for(let i=0;i<256;i++){let c=i;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;t[i]=c>>>0}return t})();
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=CRC_TABLE[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;const b=document.querySelector('#installBtn');b.hidden=false;b.onclick=async()=>{await deferredInstall.prompt();deferredInstall=null;b.hidden=true}});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));render();
